metrics.workdir_dsl:
workspace "Home Energy Management Platform" "C4 model of the home energy management platform" {

    model {
        homeowner = person "Homeowner" "A homeowner who manages their household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "A home energy management platform, owned and operated by our company" {
            dashboard = container "Dashboard Web App" "Where homeowners see consumption and costs" "Web application"
            schedulingService = container "Scheduling Service" "Plans charging and heating" "Service"
            ratesLibrary = container "Rates Library" "Computes energy prices from tariff and time of day" "Library"
            database = container "Database" "Stores meter readings and schedules" "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings, operated by a different organization"

        homeowner -> energyManager "Manages household energy use and costs"
        homeowner -> dashboard "Sees consumption and costs"
        dashboard -> ratesLibrary "Embeds"
        schedulingService -> ratesLibrary "Embeds"
        schedulingService -> smartMeterProvider "Fetches live meter readings"
        schedulingService -> database "Stores meter readings and schedules"
    }

    views {
        systemContext energyManager "SystemContext" {
            include *
            autoLayout
        }

        container energyManager "Containers" {
            include *
            autoLayout
        }
    }
}
